#!/usr/bin/env python3
"""Tiny .env loader.

Usage:
    import dotenv
    vars = dotenv.load(".env")

    python3 dotenv.py run -- CMD [ARGS...]
        Runs CMD with the variables from ./.env added to its environment.
"""

from __future__ import annotations

import os
import re
import sys

_KEY_RE = re.compile(r"^(?:export\s+)?([A-Za-z_][A-Za-z0-9_]*)$")


class DotenvError(Exception):
    """Raised when a .env file cannot be parsed."""

    def __init__(self, path: str, lineno: int, message: str):
        super().__init__(f"{path}:{lineno}: {message}")
        self.path = path
        self.lineno = lineno


def _parse_value(line: str, path: str, lineno: int) -> str:
    """Parse the value part of KEY=VALUE (already stripped)."""
    if line.startswith("'"):
        end = line.find("'", 1)
        if end == -1:
            raise DotenvError(path, lineno, "unterminated single-quoted value")
        return line[1:end]

    if line.startswith('"'):
        out = []
        i = 1
        while i < len(line):
            ch = line[i]
            if ch == '"':
                return "".join(out)
            if ch == "\\":
                if i + 1 >= len(line):
                    raise DotenvError(
                        path, lineno, "dangling escape in double-quoted value"
                    )
                esc = line[i + 1]
                if esc == "n":
                    out.append("\n")
                elif esc == "t":
                    out.append("\t")
                elif esc in ('"', "\\"):
                    out.append(esc)
                else:
                    raise DotenvError(
                        path, lineno, f"unsupported escape sequence '\\{esc}'"
                    )
                i += 2
            else:
                out.append(ch)
                i += 1
        raise DotenvError(path, lineno, "unterminated double-quoted value")

    # Unquoted: take verbatim.
    return line


def load(path: str) -> dict[str, str]:
    """Parse a .env file and return its variables as a dict."""
    result: dict[str, str] = {}
    with open(path, encoding="utf-8") as fh:
        for lineno, raw in enumerate(fh, start=1):
            line = raw.strip()

            # Blank lines and full-line comments.
            if not line or line.startswith("#"):
                continue

            lhs, sep, rhs = line.partition("=")
            if not sep:
                raise DotenvError(path, lineno, f"expected KEY=VALUE, got: {line!r}")

            key_part = lhs.strip()
            match = _KEY_RE.match(key_part)
            if not match:
                raise DotenvError(
                    path, lineno, f"invalid variable name: {key_part!r}"
                )
            key = match.group(1)

            result[key] = _parse_value(rhs.strip(), path, lineno)

    return result


def main(argv: list[str]) -> int:
    prog = argv[0] if argv else "dotenv.py"
    args = argv[1:]

    if len(args) < 2 or args[0] != "run":
        print(f"usage: {prog} run -- CMD [ARGS...]", file=sys.stderr)
        return 2

    rest = args[1:]
    if rest and rest[0] == "--":
        rest = rest[1:]
    if not rest:
        print(f"usage: {prog} run -- CMD [ARGS...]", file=sys.stderr)
        return 2

    try:
        overrides = load(os.path.join(os.getcwd(), ".env"))
    except OSError as exc:
        print(f"{prog}: cannot read .env: {exc}", file=sys.stderr)
        return 1
    except DotenvError as exc:
        print(f"{prog}: parse error: {exc}", file=sys.stderr)
        return 1

    env = dict(os.environ)
    env.update(overrides)

    try:
        os.execvpe(rest[0], rest, env)
    except OSError as exc:
        print(f"{prog}: cannot execute {rest[0]!r}: {exc}", file=sys.stderr)
        return 127


if __name__ == "__main__":
    sys.exit(main(sys.argv))

